package com.keepcalm.placementportal.repository;import com.keepcalm.placementportal.entity.Notification;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import java.time.Instant;import java.util.Optional;public interface NotificationRepository extends JpaRepository<Notification,Long>{Page<Notification> findByUserId(Long userId,Pageable p);long countByUserIdAndReadAtIsNull(Long userId);Optional<Notification> findByIdAndUserId(Long id,Long userId);@Modifying @Query("update Notification n set n.readAt=:now where n.user.id=:userId and n.readAt is null")int markAllRead(Long userId,Instant now);}
